1	/**
2	 * Shared rules for text that becomes a unit's input: which workspace paths may never be read into it, how the
3	 * candidate diff is built without them, and the credential redaction applied before it is persisted or prompted.
4	 */
5	import * as fs from "node:fs";
6	import * as os from "node:os";
7	import * as path from "node:path";
8	import { execFileSync } from "node:child_process";
9	import { createHash } from "node:crypto";
10	import { SecurityManager } from "../security.js";
11	import { MAX_SPECIALIST_INPUT_CHARS } from "./specialist_profiles.js";
12	import { redactForPersistence } from "./persistence_protection.js";
13	
14	/**
15	 * Whether a workspace-relative path is off limits as input text: protected by the workspace security policy (the one
16	 * read_file applies), or inside Nexus's own state directory (`.nexus`, compared case-insensitively because the
17	 * filesystem may be).
18	 */
19	export function inputPathProtection(security: SecurityManager, relative: string): string | undefined {
20	  const segments = relative.split(/[\\/]/).map((segment) => segment.toLowerCase());
21	  if (segments.includes(".nexus")) return "inside .nexus";
22	  const check = security.isPathProtected(relative);
23	  return check.protected ? (check.reason ?? "protected by the security policy") : undefined;
24	}
25	
26	/**
27	 * Global options for every git call that reads the workspace for a prompt. Rendering is pinned, and nothing the
28	 * repository configures may run in this process: no fsmonitor hook, no hooks, no replace objects, no system or
29	 * per-user attributes, no automatic gc. Clean/smudge filters are kept out by the attribute source below.
30	 */
31	export const GIT_SAFE = [
32	  "--no-replace-objects",
33	  "-c", "core.quotepath=false", "-c", "diff.noprefix=false", "-c", "diff.mnemonicPrefix=false", "-c", "diff.external=", "-c", "core.pager=cat",
34	  "-c", "core.fsmonitor=false", "-c", "core.hooksPath=/dev/null", "-c", "core.attributesFile=/dev/null", "-c", "core.untrackedCache=false",
35	  "-c", "gc.auto=0", "-c", "maintenance.auto=false",
36	];
37	/** Git's empty tree: as GIT_ATTR_SOURCE (Git 2.40+) it means the worktree's .gitattributes assign no attribute. */
38	const EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904";
39	
40	/**
41	 * The environment for those calls: inherited GIT_* variables (GIT_DIR, GIT_INDEX_FILE, GIT_CONFIG_PARAMETERS, ...)
42	 * are dropped, system config and system attributes are ignored, replace objects are off, and attributes come from
43	 * a tree of the worktree's own .gitattributes files with every filter and diff assignment removed (the empty tree when
44	 * there are none), so `text`/`eol` normalization still applies but no driver does. `$GIT_DIR/info/attributes` still
45	 * applies (and on Git older than 2.40 so do the worktree's .gitattributes), so a filter or diff driver assigned that
46	 * way is refused before any command could invoke it.
47	 */
48	export function safeGitEnv(indexFile: string | undefined, attrs?: { tree: string; objects: string }): NodeJS.ProcessEnv {
49	  const env: NodeJS.ProcessEnv = {};
50	  for (const [key, value] of Object.entries(process.env)) if (!key.startsWith("GIT_")) env[key] = value;
51	  return {
52	    ...env, ...(indexFile ? { GIT_INDEX_FILE: indexFile } : {}), GIT_CONFIG_NOSYSTEM: "1", GIT_ATTR_NOSYSTEM: "1", GIT_NO_REPLACE_OBJECTS: "1",
53	    GIT_ATTR_SOURCE: attrs?.tree ?? EMPTY_TREE, GIT_OPTIONAL_LOCKS: "0",
54	    ...(attrs ? { GIT_ALTERNATE_OBJECT_DIRECTORIES: attrs.objects } : {}),
55	  };
56	}
57	
58	/** Drops every `filter` and `diff` assignment (and unset/unspecify forms) from .gitattributes text, macros included. */
59	export function withoutDrivers(text: string): string {
60	  return text.split("\n").map((line) => {
61	    const trimmed = line.trim();
62	    if (!trimmed || trimmed.startsWith("#")) return line;
63	    const head = /^("(?:[^"\\]|\\.)*"|\S+)(\s+|$)/.exec(trimmed);
64	    if (!head) return line;
65	    const rest = trimmed.slice(head[0].length).split(/\s+/).filter(Boolean);
66	    return [head[1], ...rest.filter((token) => !/^[-!]?(filter|diff)(=|$)/.test(token))].join(" ");
67	  }).join("\n");
68	}
69	const DIFF_FLAGS = ["--no-color", "--no-ext-diff", "--no-textconv", "--no-renames", "--relative"];
70	const MAX_DIFF_PATHS = 2_000;
71	const GIT_MAX_BUFFER = 4 * 1024 * 1024;
72	/** Path listings scale with the repository, not the change, so they get room for very large repositories. */
73	const LISTING_MAX_BUFFER = 256 * 1024 * 1024;
74	/** Paths per `check-attr` call, so its output stays small whatever the repository's size. */
75	const ATTR_BATCH = 1_000;
76	
77	/**
78	 * Refuses (returns why) when a filter or diff driver still applies to any of `files` under the pinned attribute
79	 * source, which only `$GIT_DIR/info/attributes` (or a worktree .gitattributes on Git before 2.40) can still assign.
80	 * `run` is a pinned git call that takes stdin. Batched so a repository's size never becomes a failure.
81	 */
82	export function driverRefusal(run: (args: string[], input: string) => string, files: string[]): string | undefined {
83	  for (let start = 0; start < files.length; start += ATTR_BATCH) {
84	    const batch = files.slice(start, start + ATTR_BATCH);
85	    const checked = run(["check-attr", "-z", "--stdin", "filter", "diff"], `${batch.join("\0")}\0`).split("\0");
86	    for (let i = 0; i + 2 < checked.length; i += 3) {
87	      const [file, name, value] = [checked[i], checked[i + 1], checked[i + 2]];
88	      const safe = value === "unspecified" || value === "unset" || (name === "diff" && value === "set");
89	      if (!safe) return `a ${name} driver ('${value}') applies to ${file.slice(0, 80)} outside the worktree's .gitattributes; it is not run`;
90	    }
91	  }
92	  return undefined;
93	}
