155	/**
156	 * The attribute source for a diff: the worktree's .gitattributes files with filter and diff assignments removed, as a
157	 * tree in a private object directory (nothing is written to the repository). Undefined when there are none.
158	 */
159	export function attributesTree(root: string, scratch: string, files: string[]): { tree: string; objects: string } | undefined {
160	  const sources = files.filter((f) => path.posix.basename(f) === ".gitattributes").flatMap((f) => {
161	    try {
162	      const full = path.join(root, f);
163	      const st = fs.lstatSync(full);
164	      return st.isFile() && st.size <= 1024 * 1024 ? [{ file: f, text: withoutDrivers(fs.readFileSync(full, "utf8")) }] : [];
165	    } catch { return []; }
166	  });
167	  if (!sources.length) return undefined;
168	  const objects = path.join(scratch, "attr-objects");
169	  fs.mkdirSync(objects);
170	  const env = { ...safeGitEnv(path.join(scratch, "attr-index")), GIT_OBJECT_DIRECTORY: objects };
171	  const run = (args: string[], input?: string) => execFileSync("git", [...GIT_SAFE, ...args], { cwd: root, env, encoding: "utf8", stdio: [input === undefined ? "ignore" : "pipe", "pipe", "pipe"], timeout: 30_000, ...(input === undefined ? {} : { input }) });
172	  const entries = sources.map(({ file, text }) => `100644 ${run(["hash-object", "-w", "--stdin"], text).trim()}\t${file}\0`);
173	  run(["update-index", "--add", "-z", "--index-info"], entries.join(""));
174	  return { tree: run(["write-tree"]).trim(), objects };
175	}
