177	/**
178	 * The candidate diff against `base` (HEAD when absent), for every unit that is shown one: review units and the
179	 * security reviewer. No repository-configured command runs while it is built (see GIT_SAFE and safeGitEnv); a
180	 * filter or diff driver that would still apply makes it fail. It is built from the changed paths and never from parsing diff text: the changed paths come from
181	 * NUL-separated git output with rendering options pinned, the protected ones (the read_file policy, `.nexus`) are
182	 * removed, and the diff is then requested for the remaining paths only (literal pathspecs), so a protected file cannot
183	 * appear in it whatever the repository's diff settings. A rename or copy with either side protected drops both sides
184	 * (the body of a file renamed out of a protected path is still its content).
185	 *
186	 * Untracked files are compared through a scratch index (the base tree plus intent-to-add entries for every untracked
187	 * file, never the repository's own index), so git's rename detection pairs an unstaged move of a protected file with
188	 * its new name instead of showing that name as an unrelated new file. Rename and copy detection stop at git's
189	 * similarity threshold (and `--find-copies-harder` makes an untouched tracked protected file a copy source), so when
190	 * any protected path changed (moved, deleted, edited or added), every added file is omitted too and counted in
191	 * `omittedNew`: a protected file moved and rewritten, or one whose lines were copied out, may otherwise reach the diff
192	 * as an innocent new file. Independently of git's heuristics, an added file is omitted (and counted the same way) when
193	 * it equals a protected file present in the workspace, tracked, untracked or ignored, or shares a significant line
194	 * with one (see `protectedContent`); that covers `cp .env notes.txt` and a partial copy of any size.
195	 * Limits of that comparison, where credential redaction is the only guard: lines pasted from a protected file into a
196	 * file that already existed at the base (modified files are not line-compared); any re-formatting of a protected
197	 * file's lines (quoting, a changed separator, values only, re-encoding), because a line matches only exactly once
198	 * trimmed and is at least 8 characters; and a protected file whose lines are all shorter than that, which is caught
199	 * only by an exact whole-file match. The trade-off is over-omission: a new file sharing a common line (such as
200	 * NODE_ENV=development) with any protected file in the workspace, an ignored `.env*` included, is omitted and noted.
201	 * The pass listing ignored files takes up to IGNORED_LISTING_TIMEOUT_MS (about 6 s per 90k ignored files); a tree too
202	 * large for it fails closed with an error rather than being trusted.
203	 * Any git failure or an unmanageable path count returns an error: nothing is ever kept because it could not be
204	 * classified.
205	 */
206	export interface CandidateDiff { base: string; diff: string; omitted: number; omittedNew: number; omittedNested: number }
207	export function candidateDiff(workspace: string, base: string | undefined, policyWorkspace?: string): CandidateDiff | { error: string } {
208	  const root = path.resolve(workspace);
209	  let scratch: string | undefined;
210	  let attrs: { tree: string; objects: string } | undefined;
211	  // `ownIndex` reads the repository's own index (never written: only listed); everything else uses the scratch index.
212	  const git = (args: string[], options: { okExit?: number[]; input?: string; maxBuffer?: number; ownIndex?: boolean; timeoutMs?: number } = {}): string => {
213	    try {
214	      return execFileSync("git", [...GIT_SAFE, ...args], {
215	        cwd: root, env: safeGitEnv(options.ownIndex ? undefined : path.join(scratch!, "index"), attrs), encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"],
216	        timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER, ...(options.input === undefined ? {} : { input: options.input }),
217	      });
218	    } catch (err: any) {
219	      if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
220	      throw err;
221	    }
222	  };
223	  try {
224	    scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-candidate-index-"));
225	    // The policy is the operator's (their workspace), not whatever a unit's own worktree holds: an untracked
226	    // .nexus-security.json never reaches a worktree.
227	    const security = new SecurityManager(policyWorkspace ?? root);
228	    // A base read from persisted JSON is resolved as a commit before use: a value shaped like an option is refused.
229	    const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
230	    git(["read-tree", "--end-of-options", commit]);
231	    const listing = (args: string[], ownIndex = false, timeoutMs?: number) => git(["ls-files", "-z", ...args], { maxBuffer: LISTING_MAX_BUFFER, ownIndex, timeoutMs }).split("\0").filter(Boolean);
232	    // New paths: untracked files git does not ignore, plus files tracked now but not at the base (a force-added file
233	    // can match .gitignore and still be part of the candidate).
234	    const atBase = new Set(listing([]));
235	    // A path tracked since the base but already removed from disk is a deletion against nothing: it has no content to
236	    // show, and git would reject it as a pathspec.
237	    const onDisk = (p: string) => { try { fs.lstatSync(path.join(root, p)); return true; } catch { return false; } };
238	    const ownIndex = new Set(listing([], true));
239	    // Untracked, non-ignored entries, listed once. A directory entry (trailing slash) is an untracked nested git
240	    // repository, which `git add` refuses: it is skipped and counted rather than failing every review.
241	    const others = listing(["--others", "--exclude-standard"]);
242	    const omittedNested = others.filter((p) => p.endsWith("/")).length;
243	    const untracked = others.filter((p) => !p.endsWith("/"));
244	    attrs = attributesTree(root, scratch, [...new Set([...untracked, ...ownIndex])]);
245	    // A path tracked at the base but removed from the real index (`git rm --cached`) is part of the candidate as a
246	    // deletion even when the file stays on disk: force it out of the scratch index too (its entry can match neither HEAD nor the worktree), and never re-add it as new.
247	    const removed = [...atBase].filter((p) => !ownIndex.has(p));
248	    if (removed.length) {
249	      git(["--literal-pathspecs", "rm", "--cached", "--force", "--quiet", "--ignore-unmatch", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${removed.join("\0")}\0` });
250	    }
251	    // The real index can hold a mode the base lacks while the file's mode on disk is not trusted (core.filemode=false,
252	    // `git update-index --chmod=+x`). The scratch index only knows the base's, so carry over each tracked path's current
253	    // executable bit (the mode is read from the real index; nothing the repository configures runs to read it).
254	    const modeOf = (entries: string[]) => new Map(entries.filter(Boolean).flatMap((e) => {
255	      const m = /^(\d{6}) ([0-9a-f]+) (\d)\t([\s\S]*)$/.exec(e);
256	      return m && m[3] === "0" ? [[m[4], { mode: m[1], oid: m[2] }] as const] : [];
257	    }));
258	    const baseModes = modeOf(git(["ls-files", "-s", "-z"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0"));
259	    const ownModes = modeOf(git(["ls-files", "-s", "-z"], { maxBuffer: LISTING_MAX_BUFFER, ownIndex: true }).split("\0"));
260	    const modeChanges: string[] = [];
261	    for (const [file, own] of ownModes) {
