  /** Fixed author, no signing and no hooks (pre or post): integration must not depend on the operator's Git config. */
  private mechanicalGitConfig(): string[] {
    const base = ["-c", "user.name=Nexus", "-c", "user.email=nexus@localhost", "-c", "commit.gpgsign=false"];
    try {
      fs.mkdirSync(this.hooksDir, { recursive: true });
      return [...base, "-c", `core.hooksPath=${this.hooksDir}`];
    } catch {
      // Without a usable hooks directory, `--no-verify` still skips pre-commit/commit-msg; post-* hooks may run.
      return base;
    }
  }

  private abortStaleMerge(): void {
    try {
      const gitDirPath = git(this.plan.integrationWorktree, ["rev-parse", "--git-dir"]);
      const gitDir = path.isAbsolute(gitDirPath) ? gitDirPath : path.resolve(this.plan.integrationWorktree, gitDirPath);
      if (fs.existsSync(path.join(gitDir, "MERGE_HEAD"))) {
      }
      return { protected: false };
    };

    // 1. Raw given path
    const rawCheck = checkCandidate(targetPath);
    if (rawCheck.protected) return rawCheck;

    // 2. Absolute path in workspace
    const absPath = path.isAbsolute(targetPath) ? targetPath : path.resolve(this.workspace, targetPath);
    const absCheck = checkCandidate(absPath);
    if (absCheck.protected) return absCheck;

    // 3. Canonical target (resolves symlinks)
    try {
      if (fs.existsSync(absPath)) {
        const real = fs.realpathSync(absPath);
        const realCheck = checkCandidate(real);
        if (realCheck.protected) {
          return {
            protected: true,
            reason: `Security Policy Violation: Path '${targetPath}' resolves to protected target '${real}'`,
          };
        }
      } else {
        const dir = path.dirname(absPath);
        if (fs.existsSync(dir)) {
          const realDir = fs.realpathSync(dir);
          const canonicalTarget = path.join(realDir, path.basename(absPath));
          const canonCheck = checkCandidate(canonicalTarget);
          if (canonCheck.protected) return canonCheck;
        }
      }
    } catch {}

    return { protected: false };
  }

  public getPolicy(): SecurityPolicy {
    return this.policy;
  }

